// Not an official Synthux Academy product; not affiliated with Synthux Academy.
//
// Host-facing wrapper around the Spotykach core. It hides every firmware assumption:
//   * the core runs at a fixed internal 48 kHz; this class resamples to and from the host rate
//     (no resampling at all when the host is already at 48 kHz);
//   * the core's 2 ms clock/prepare tick is generated by counting engine samples, so any host
//     block size works;
//   * all memory belongs to the instance and is allocated here, never on the audio thread.
//
// Threading: construct and prepare() on a non-audio thread. process() is the only call allowed
// on the audio thread. The status atomics may be read from any thread.
#pragma once
#include <atomic>
#include <cstdint>
#include <memory>

namespace usp
{
    struct DeckParams
    {
        float position = 0.0f;   // 0..1
        float size     = 1.0f;   // 0..1
        float pitch    = 0.5f;   // 0..1, 0.5 = normal speed
        float envelope = 0.0f;   // 0..1, 0 = off
        float mix      = 0.5f;   // deck in/out mix: 0 = input only, 1 = loop only
        float feedback = 0.95f;  // 0..1 (overdub level)
        int   mode     = 0;      // 0 = Reel, 1 = Slice, 2 = Drift
        float sliceOffset = 0.0f; // 0..1 (Slice: step through slices; has an effect only when the loop has slices)
        float envLength   = 1.0f; // 0..1 (Drift only)
        float window      = 0.2f; // 0..1 (Drift only: grain size)
        int   pitchSnap   = 0;   // 0 = off, 1 = firmware steps (-24 -12 -7 0 +7 +12 +24 st), 2 = semitones

        // Flux (delay) and Grit (drive / reduce / filter); defaults are the firmware's.
        bool  fluxOn = false;
        int   fluxMode = 0;      // 0 = Free (10 ms to 2 s), 1 = Clocked (note divisions of the tempo)
        float fluxTime = 0.5f;
        float fluxFeedback = 0.5f;
        float fluxMix = 0.7f;
        bool  gritOn = false;
        int   gritMode = 0;      // 0 = Drive, 1 = Reduce, 2 = Filter
        float gritIntensity = 0.2f;
        float gritMix = 0.33f;
        float gritCharacter = 0.0f;   // Filter mode only (resonance)
    };

    enum EngineRoute : int { kRouteDoubleMono = 0, kRouteStereo = 1, kRouteGenerativeStereo = 2 };

    struct EngineParams
    {
        DeckParams deck[2];          // 0 = Deck A, 1 = Deck B
        float crossfade = 0.5f;      // 0 = Deck A only, 1 = Deck B only (square-law crossfade)
        int   route     = kRouteStereo;
        float panSpeed  = 1.0f;      // Generative Stereo only
        float panRange  = 0.6f;      // Generative Stereo only
        float tempoBpm  = 120.0f;    // internal tempo, 20..250
        bool  hostSync  = false;     // follow the host's tempo and beat position
        int   launchQuantise = 1;    // index 0..16 into the firmware's list (1/16, 1/4, 2/4 ... 16/4)
        float clickLevel = 0.0f;     // 0..1
    };

    struct HostTransport
    {
        bool   playing = false;
        bool   hasTempo = false;
        double bpm = 120.0;
        bool   hasPpq = false;
        double ppq = 0.0;            // quarter-note position at the start of the block
    };

    // Rising-edge button presses, as bit flags. Deck A uses bits 0-7, Deck B bits 8-15.
    enum EngineAction : uint32_t
    {
        kActionRecord         = 1u << 0,   // arm / stop recording from the plug-in input
        kActionPlay           = 1u << 1,   // play forward / stop
        kActionReverse        = 1u << 2,   // play reverse / stop
        kActionTrig           = 1u << 3,   // trigger (restarts playback; the firmware's gate input)
        kActionRecordInternal = 1u << 4    // arm / stop recording from the OTHER deck's output
    };
    constexpr uint32_t deckAction (int deck, EngineAction a) { return (uint32_t) a << (deck * 8); }

    struct DeckStatus
    {
        std::atomic<bool>     armed { false };
        std::atomic<bool>     recording { false };
        std::atomic<bool>     playing { false };
        std::atomic<bool>     reverse { false };
        std::atomic<bool>     empty { true };
        std::atomic<float>    loopSeconds { 0.0f };
        std::atomic<float>    playhead { 0.0f };       // 0..1 through the loop
    };

    struct EngineStatus
    {
        DeckStatus deck[2];
        std::atomic<bool>     hostLocked { false };    // clock is locked to the host's beat
        std::atomic<float>    tempoBpm { 120.0f };     // tempo the engine is actually using
        std::atomic<uint32_t> underruns { 0 };         // output frames the resampler could not supply
    };

    class Engine
    {
    public:
        Engine();
        ~Engine();

        // Non-audio thread. Safe to call again when the host rate changes; recorded audio is kept.
        void prepare (double hostSampleRate, int maxHostBlock);

        // Latency this wrapper adds, in host samples (0 at 48 kHz).
        int latencySamples() const;

        // Audio thread. in/out may be the same arrays. n may be any size >= 0.
        void process (const float* inL, const float* inR, float* outL, float* outR, int n,
                      const EngineParams& params, uint32_t actions, const HostTransport& host = HostTransport());

        const EngineStatus& status() const { return statusValues; }

    private:
        EngineStatus statusValues;   // declared first: Impl keeps a reference to it
        struct Impl;
        std::unique_ptr<Impl> impl;
    };
}
